from atexit import register
from typing import Any

from requests.exceptions import HTTPError
from requests.auth import HTTPBasicAuth
import time
from os import getenv

import requests
import uuid
import json
from weakref import WeakValueDictionary

from taf.gnb.oam.coam.cu.utilities.logger import (
    log_sending_message,
    log_received_response,
    log_warning,
)
from taf.gnb.oam.coam.cu.utilities.token_storage import TokenStorage
from taf.gnb.oam.coam.cu.utilities.basic_access_token import get_basic_access_token
from taf.gnb.oam.coam.cu.utilities.update_expired_password import (
    update_expired_password,
)
from taf.gnb.oam.coam.cu.exception import AuthenticationFailed, ApiException


class SECv1:
    """This class provides a client for the SEC v1 API"""

    _instances: Any = WeakValueDictionary()

    def __new__(cls, con_details=None, *args, **kwargs):
        connection_name = con_details.alias

        if connection_name not in cls._instances:
            instance = super().__new__(cls)
            cls._instances[connection_name] = instance
        return cls._instances[connection_name]

    def __init__(self, con_details=None):
        if not hasattr(self, "_initialized"):
            self._initialized = True

            self.con_details = con_details
            self.token_storage = TokenStorage(connection_name=con_details.alias)
            self.url = con_details.make_configuration_host(
                original_endpoint="http://localhost/api/sec/v1"
            )
            self.disable_logging = (
                getenv("TAF_VDU_CLIENT_DISABLE_LOGGING", "False").lower() == "true"
            )

    @classmethod
    def get_instance(cls, connection_name):
        return cls._instances[connection_name]

    @classmethod
    def remove_instance(cls, connection_name):
        if connection_name in cls._instances:
            cls._instances[connection_name].token_storage.remove_instance(
                connection_name=connection_name
            )
            del cls._instances[connection_name]

    @classmethod
    def clear_instances(cls):
        for connection_name, instance in cls._instances.items():
            instance.token_storage.remove_instance(connection_name)
        cls._instances.clear()

    def login(self, username, password, need_login_info=False, timeout=None):
        response = self._login(username=username, password=password, timeout=timeout)
        try:
            response.raise_for_status()

        except HTTPError as e:
            if e.response.status_code == 401:
                response = self._handle_error_401(username=username)

            elif e.response.status_code == 403:
                response = self._handle_error_403(response_content=response, username=username)

        if response.status_code != 403:
            try:
                response.raise_for_status()
            except HTTPError:
                raise ApiException(http_response=response)

        token_data = response.json()

        self.token_storage.access_token = token_data["Token"]
        self.token_storage.expires_at = token_data["Expires"]

        return token_data if need_login_info else token_data["Token"]

    def logout(self, timeout=None):
        request_id = str(uuid.uuid4())
        endpoint = f"{self.url}/logout"
        headers = {
            "Authorization": f"Bearer {self.token_storage.access_token}",
            "accept": "*/*",
        }

        if not self.disable_logging:
            log_sending_message(
                request_id=request_id,
                endpoint=endpoint,
                headers=headers,
                method="POST",
                connection_alias=self.con_details.alias,
            )

        response = requests.post(
            url=endpoint, headers=headers, verify=False, timeout=timeout
        )

        if not self.disable_logging:
            log_received_response(
                request_id=request_id,
                response=response,
                endpoint=endpoint,
                method="POST",
                connection_alias=self.con_details.alias,
            )

    def get_sessions_list(self, timeout):
        request_id = str(uuid.uuid4())
        endpoint = f"{self.url}/sessions"
        headers = {
            "Authorization": f"Bearer {self.token_storage.access_token}",
            "accept": "application/json",
        }

        if not self.disable_logging:
            log_sending_message(
                request_id=request_id,
                endpoint=endpoint,
                headers=headers,
                method="GET",
                connection_alias=self.con_details.alias
            )

        response = requests.get(
            url=endpoint,
            headers=headers,
            timeout=timeout,
            verify=False
        )

        if not self.disable_logging:
            log_received_response(
                request_id=request_id,
                response=response,
                endpoint=endpoint,
                method="GET",
                connection_alias=self.con_details.alias,
            )
        response.raise_for_status()

        return response.json()

    def refresh_token(self, username, password):
        request_id = str(uuid.uuid4())
        endpoint = f"{self.url}/refresh-token"
        headers = {"Content-Type": "application/json"}
        request_body = json.dumps({"Type": "Bearer", "Token": self.token_storage.access_token})

        if not self.disable_logging:
            log_sending_message(
                request_id=request_id,
                endpoint=endpoint,
                headers=headers,
                method="PATCH",
                connection_alias=self.con_details.alias,
            )

        response = requests.patch(
            url=endpoint,
            data=request_body,
            headers=headers,
            verify=False,
            auth=HTTPBasicAuth(username, password)
        )

        if not self.disable_logging:
            log_received_response(
                request_id=request_id,
                response=response,
                endpoint=endpoint,
                method="PATCH",
                connection_alias=self.con_details.alias,
            )
        response.raise_for_status()

        token_data = response.json()
        self.token_storage.access_token = token_data["Token"]
        self.token_storage.expires_at = token_data["Expires"]

        return token_data

    def get_token_info(self, timeout=None):
        request_id = str(uuid.uuid4())
        endpoint = f"{self.url}/token-info"
        headers = {
            "Authorization": f"Bearer {self.token_storage.access_token}",
            "accept": "application/json",
        }

        if not self.disable_logging:
            log_sending_message(
                request_id=request_id,
                endpoint=endpoint,
                headers=headers,
                method="GET",
                connection_alias=self.con_details.alias,
            )

        response = requests.get(
            url=endpoint,
            headers=headers,
            verify=False,
            timeout=timeout
        )

        if not self.disable_logging:
            log_received_response(
                request_id=request_id,
                response=response,
                endpoint=endpoint,
                method="GET",
                connection_alias=self.con_details.alias,
            )
        response.raise_for_status()

        return response.json()

    def _login(self, username, password, timeout=None):
        headers = {
            "Authorization": f"Basic {get_basic_access_token(username=username, password=password)}",
            "Content-Type": "application/json",
            "accept": "application/json",
        }
        endpoint = self.url + "/login"
        request_id = str(uuid.uuid4())

        if not self.disable_logging:
            log_sending_message(
                request_id=request_id,
                endpoint=endpoint,
                headers=headers,
                method="POST",
                connection_alias=self.con_details.alias,
            )

        response = requests.post(
            url=endpoint,
            headers=headers,
            data=json.dumps({"ReadOnlyMode": self.con_details.read_only}),
            verify=False,
            timeout=timeout,
        )

        if not self.disable_logging:
            log_received_response(
                request_id=request_id,
                response=response,
                endpoint=endpoint,
                method="POST",
                connection_alias=self.con_details.alias,
            )
        return response

    def _handle_error_401(self, username):
        if self.con_details.password == "nemuuser":
            return self._log_in_using_default_password(username=username)

        else:
            raise AuthenticationFailed(
                f"Login using provided password - {self.con_details.password} failed. If this is your first "
                "login after deployment - try connecting again using 'nemuuser'"
            )

    def _handle_error_403(self, response_content, username):
        if not self.con_details.update_expired_password:
            log_warning(
                f"Password you gave: {self.con_details.password} expired. "
                "Please update your password manually as automatic update was disabled."
            )
            return response_content

        return self._update_expired_password(
            username=username, response_content=response_content
        )

    def _log_in_using_default_password(self, username):
        if not self.disable_logging:
            log_warning(
                "IMPORTANT: this functionality is deprecated and will be removed in the future! "
                "Password you gave: nemuuser is incorrect, "
                "(it was probably changed during first login after deployment), "
                "trying to log in using default password - Nokia@123."
            )

        time.sleep(5)  # account is locked for 5 seconds after failed login

        return self._login(username=username, password="Nokia@123")

    def _update_expired_password(self, username, response_content):
        default_password = "Nokia@123"

        self.token_storage.access_token = response_content.json()["Token"]
        update_expired_password(
            connection_details=self.con_details, new_password=default_password
        )
        time.sleep(1)  # account is locked for 1 second after password update

        return self._login(username=username, password=default_password)

register(SECv1.clear_instances)
